jobs=[job('total','Касса для «Ложки»','Сумма заказа = цена одного блюда × количество. При нуле блюд сумма тоже нулевая.','total','fn total(price, count) {\n  return price * count;\n}',650,90,['Умножить цену на количество','Сложить цену и количество','Вычесть количество из цены'],[([70,2],140),([55,3],165),([30,0],0)]),job('discount','Скидка для кофейни','При сумме от 500 ₽ включительно дать скидку 10%. Ниже 500 ₽ цена не меняется.','discount','fn discount(sum) {\n  return sum >= 500 ? sum * 0.9 : sum;\n}',950,120,['Скидка при сумме >= 500','Скидка только при сумме > 500','Оставить сумму без проверки'],[([400],400),([500],450),([800],720)]),job('delivery','Тариф доставки','До 3 км включительно доставка стоит 100 ₽. Дальше — 200 ₽.','delivery','fn delivery(distance) {\n  return distance <= 3 ? 100 : 200;\n}',800,105,['Ближняя зона: расстояние <= 3','Ближняя зона: расстояние < 3','Игнорировать границу зон'],[([1],100),([3],100),([6],200)])]
